                    j += 1
                yield (True, int(s[i:j]))
                i = j
            else:
                j = i
                while j < n and not (s[j].isdigit() and ord(s[j]) <= 0x7F):
                    j += 1
                yield (False, s[i:j])
                i = j

    @functools.cmp_to_key
    def _compare(a, b):
        sa = list(_split(a))
        sb = list(_split(b))
        # Compare run by run
        for (ad, av), (bd, bv) in zip(sa, sb):
            if ad != bd:
                # text token (False) sorts before numeric token (True)
                return -1 if ad is False else 1
            if av < bv:
                return -1
            if av > bv:
                return 1
        # One list is a prefix of the other
        if len(sa) < len(sb):
            return -1
        if len(sa) > len(sb):
            return 1
        # Equal keys preserve input order
        return 0

    return sorted(strings, key=functools.cmp_to_key(_compare))

