def natural_sort_strings(strings):
    """Sort a list of strings by natural order.

    Splits each string into maximal ASCII-digit and non-digit runs.
    Digit runs compare by integer value; non-digit runs compare
    case-sensitive Unicode lexical order. Text tokens sort before
    numeric tokens when kinds differ. Shorter equal-prefix token
    lists sort first; equal keys preserve input order. Empty strings
    are allowed; Unicode digits are treated as text.
    """
    def _key(s):
        runs = []
        i = 0
        n = len(s)
        while i < n:
            # collect a maximal digit run (ASCII only)
            if s[i].isdigit() and ord(s[i]) < 128:
                j = i
                while j < n and s[j].isdigit() and ord(s[j]) < 128:
                    j += 1
                runs.append(('digit', int(s[i:j])))
                i = j
            else:
                j = i
                while j < n and not (s[j].isdigit() and ord(s[j]) < 128):
                    j += 1
                runs.append(('text', s[i:j]))
                i = j
        # secondary key: 0 for text-first token, 1 for digit-first
        # this ensures text tokens sort before numeric tokens when kinds differ
        secondary = 0
        if runs:
            if runs[0][0] == 'digit':
                secondary = 1
        return (runs, secondary)

    return sorted(strings, key=_key)
